package main

import (
	"encoding/json"
	"log"
	"sync"
	"time"

	m "github.com/jepsen-io/maelstrom/demo/go/maelstrom"
)

const (
	customType = "gv" // gossip: carries a list of rumor values in field "v"
	syncPeriod = 200 * time.Millisecond
)

func main() {
	n := m.NewNode()

	var mu sync.Mutex
	known := make(map[int64]struct{})

	// peers returns all node IDs except self.
	peers := func() []string {
		var out []string
		for _, id := range n.NodeIDs() {
			if id != n.ID() {
				out = append(out, id)
			}
		}
		return out
	}

	// learn merges values into the set, returning those new to us.
	learn := func(vals []int64) []int64 {
		mu.Lock()
		defer mu.Unlock()
		var fresh []int64
		for _, v := range vals {
			if _, ok := known[v]; !ok {
				known[v] = struct{}{}
				fresh = append(fresh, v)
			}
		}
		return fresh
	}

	// gossip sends vals (nil = everything we know) to all peers.
	gossip := func(vals []int64) {
		if vals == nil {
			mu.Lock()
			vals = make([]int64, 0, len(known))
			for v := range known {
				vals = append(vals, v)
			}
			mu.Unlock()
		}
		if len(vals) == 0 {
			return
		}
		body := map[string]any{"type": customType, "v": vals}
		for _, p := range peers() {
			if err := n.Send(p, body); err != nil {
				log.Printf("gossip to %s failed: %v", p, err)
			}
		}
	}

	n.Handle("tell", func(msg m.Message) error {
		var body struct {
			Rumor int64 `json:"rumor"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}
		fresh := learn([]int64{body.Rumor})
		if len(fresh) > 0 {
			gossip(fresh)
		}
		return n.Reply(msg, map[string]any{"type": "told"})
	})

	n.Handle("recall", func(msg m.Message) error {
		mu.Lock()
		vals := make([]int64, 0, len(known))
		for v := range known {
			vals = append(vals, v)
		}
		mu.Unlock()
		return n.Reply(msg, map[string]any{"type": "recalled", "rumors": vals})
	})

	n.Handle("neighbors", func(msg m.Message) error {
		return n.Reply(msg, map[string]any{"type": "neighbors_noted"})
	})

	n.Handle(customType, func(msg m.Message) error {
		var body struct {
			Vals []int64 `json:"v"`
		}
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}
		fresh := learn(body.Vals)
		if len(fresh) > 0 {
			gossip(fresh)
		}
		return nil
	})

	// Periodic anti-entropy: push the full rumor set to every peer, forever.
	go func() {
		// Wait for init.
		for len(n.NodeIDs()) == 0 {
			time.Sleep(20 * time.Millisecond)
		}
		for {
			time.Sleep(syncPeriod)
			gossip(nil)
		}
	}()

	if err := n.Run(); err != nil {
		log.Fatalf("run: %v", err)
	}
}
